insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'میں عمر رضی اللہ عنہ کے ساتھ عید کے دن حاضر ہوا؛ انہوں نے خطبے سے پہلے نماز پڑھی، پھر فرمایا: رسول اللہ ﷺ نے ان دو دنوں کے روزے سے منع فرمایا ہے۔ عید الاضحی کے دن تم اپنی قربانیوں کے گوشت کھاتے ہو، اور عید الفطر کے دن تم اپنے روزے افطار کرتے ہو۔');
