insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.voluntary.reasons[1].cites[0].quote', 'میں اللہ تعالیٰ سے امید رکھتا ہوں کہ یومِ عرفہ کا روزہ گزشتہ اور آئندہ سال کے گناہوں کا کفارہ بن جائے گا، اور یومِ عاشوراء کا روزہ گزشتہ سال کے گناہوں کا کفارہ بن جائے گا۔');
