insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'آپ کے لیے بس اتنا کافی ہے کہ ہر مہینے میں تین دن روزے رکھیں، کیونکہ نیکی کا بدلہ دس گنا ہے؛ پس یہ سارے سال کے روزوں کی مانند ہے۔');
