insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'ہر مہینے کے تین دن کے روزے اور ہر سال رمضان کے روزے، یہ سدا کا روزہ ہے۔');
