insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.voluntary.reasons[3].cites[3].quote', 'جو ہر مہینے میں تین دن روزے رکھے، تو یہ ہمیشہ کے روزے کی مانند ہے۔');
