insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'ہر مہینے کے تین دن کے روزے ہمیشہ کے روزے کی مانند ہیں، اور ایامِ بیض تیرہ، چودہ اور پندرہ تاریخ ہیں۔');
