insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'میرے خلیل ﷺ نے مجھے تین چیزوں کی وصیت فرمائی: ہر مہینے میں تین دن روزے رکھنے، چاشت کی دو رکعتیں پڑھنے اور سونے سے پہلے وتر پڑھنے کی۔');
