insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'میرے خلیل ﷺ نے مجھے تین چیزوں کی ہدایت فرمائی، جنہیں میں کبھی نہیں چھوڑتا؛ انہوں نے مجھے ہر مہینے میں تین دن روزے رکھنے کی ہدایت فرمائی۔');
