insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'اسامہ بن زید رضی اللہ عنہما روایت کرتے ہیں کہ رسول اللہ ﷺ نے فرمایا:');
insert into i18n_bundles (locale, code, value) values ('ur', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'یہ دو دن ہیں جن میں اعمال رب العالمین کے سامنے پیش کیے جاتے ہیں، اور میں پسند کرتا ہوں کہ میرے اعمال اس وقت پیش کیے جائیں جب میں روزے سے ہوں۔');
